use std::{path::PathBuf, str::FromStr, sync::LazyLock};

use exposed::{
    config::Config, domain::models::entity_search::EntitySearchRequest,
    inbound::http::server::serve_exposed,
};
use reqwest::StatusCode;
use serde_json::Value;

const TEST_CONFIG: LazyLock<Config> = LazyLock::new(|| {
    let test_config = PathBuf::from_str("config/test.yaml").unwrap();
    let config = Config::try_from(&test_config).unwrap();
    config
});

pub struct Guard;

pub async fn search_entities(params: &EntitySearchRequest) -> anyhow::Result<Vec<Value>> {
    let client = reqwest::Client::new();
    let port = TEST_CONFIG.port;

    let (term, strictness, entries) = (params.term(), params.strictness(), params.max_entries());
    let url = format!(
        "http://127.0.0.1:{port}/search?term={term}&&strictness={strictness}&&max_entries={entries}"
    );
    let response = client.get(url).send().await?;

    match response.status() {
        StatusCode::OK => {
            let bytes = response.bytes().await?;
            let data: Value = serde_json::from_slice(&bytes)?;
            let entities = data
                .get("entities")
                .and_then(|d| d.as_array())
                .ok_or(anyhow::anyhow!("unparsable"))?
                .to_vec();
            return Ok(entities);
        }
        StatusCode::INTERNAL_SERVER_ERROR => {
            return Err(anyhow::anyhow!("something unexpected happened"));
        }
        StatusCode::UNPROCESSABLE_ENTITY => return Err(anyhow::anyhow!("bad url")),
        _ => {
            return Err(anyhow::anyhow!(
                "something really unexpected happened, investigate"
            ));
        }
    }
}

pub async fn start_app() -> anyhow::Result<Guard> {
    let _handle = tokio::task::spawn(async move {
        let _ = serve_exposed(&TEST_CONFIG).await;
        println!("started");
    });

    Ok(Guard)
}
//! Integration test for the entity seacrh endpoint.
//! This test suite expects a pre-loaded database.
//!
//!

use std::{collections::HashMap, time::Duration};

use exposed::domain::models::entity_search::EntitySearchRequest;
use tokio::time;

use crate::common::{search_entities, start_app};

mod common;

#[tokio::test]
async fn shows_no_hsbc_duplicates() {
    let _guard = start_app().await.unwrap();
    time::sleep(Duration::from_secs(2)).await;

    let known_duplicate = EntitySearchRequest::new_with_strictness("HSBC".into(), 10, 0.9).unwrap();
    let entities = search_entities(&known_duplicate).await.unwrap();

    let mut duplicates: HashMap<String, usize> = HashMap::new();
    for e in entities.into_iter() {
        duplicates
            .entry(e.get("name").unwrap().as_str().unwrap().into())
            .and_modify(|count| *count += 1)
            .or_insert(1);
    }

    assert_eq!(duplicates.get("HSBC UK Bank plc"), Some(&1));
    assert_eq!(duplicates.get("HSBC UK Bank PLC"), Some(&1));
    assert_eq!(duplicates.get("HSBC UK (Ian Stuart, CEO)"), Some(&1));
}
//! Representatives of the public in parliament.

/// Member of Parliament
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ParliamentMember {
    name: ParliamentMemberName,
    _member_id: MemberId,
    _party_name: PartyName,
    _constituency: Constituency,
}

impl ParliamentMember {
    #[must_use]
    /// Creates a new Member of Parliament
    pub const fn new(
        name: String,
        member_id: usize,
        party_name: String,
        constituency: String,
    ) -> Self {
        Self {
            name: ParliamentMemberName::new(name),
            _member_id: MemberId::new(member_id),
            _party_name: PartyName::new(party_name),
            _constituency: Constituency::new(constituency),
        }
    }

    #[must_use]
    /// Member's name
    pub fn name(&self) -> &str {
        &self.name.0
    }
}

/// Member name
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ParliamentMemberName(String);

impl ParliamentMemberName {
    #[must_use]
    /// Creates member name
    pub const fn new(name: String) -> Self {
        Self(name)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Party name
#[allow(dead_code)]
pub struct PartyName(String);

impl PartyName {
    #[must_use]
    /// Create party name
    pub const fn new(name: String) -> Self {
        Self(name)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Member constituency
#[allow(dead_code)]
pub struct Constituency(String);

impl Constituency {
    #[must_use]
    /// Creates member constituency
    pub const fn new(name: String) -> Self {
        Self(name)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Member parliament API ID
#[allow(dead_code)]
pub struct MemberId(usize);

impl MemberId {
    #[must_use]
    /// Creates member parliament API ID
    pub const fn new(id: usize) -> Self {
        Self(id)
    }
}
//! Concrete implementation of the repository

use crate::{
    domain::{
        models::{
            entity_search::EntitySearchRequest, parliament_member::ParliamentMember,
            search_similarity::SearchSimilarity,
        },
        repositories::parliament_member_repository::{
            ParliamentMemberRepo, ParliamentMemberRepoError,
        },
    },
    outbound::postgres::ExposedDatabase,
};

impl ParliamentMemberRepo for ExposedDatabase {
    #[allow(clippy::cast_sign_loss)]
    async fn get_members_by_text_search_score(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<Vec<(ParliamentMember, SearchSimilarity)>, ParliamentMemberRepoError> {
        sqlx::query!(
            "
            SELECT  
                m.name,
