#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct History { id: i32, house_membership_history: Vec<Membership> }
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Membership { house: i16, membership_start_date: SourceDate, membership_end_date: Option<SourceDate> }

struct SourceDate(NaiveDate);
impl<'de> Deserialize<'de> for SourceDate {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let value = String::deserialize(deserializer)?;
        let date = NaiveDate::parse_from_str(&value, "%Y-%m-%d")
            .or_else(|_| DateTime::parse_from_rfc3339(&value).map(|d| d.date_naive()))
            .or_else(|_| NaiveDateTime::parse_from_str(&value, "%Y-%m-%dT%H:%M:%S%.f").map(|d| d.date()))
            .or_else(|_| NaiveDateTime::parse_from_str(&value, "%Y-%m-%d %H:%M:%S%.f").map(|d| d.date()))
            .map_err(serde::de::Error::custom)?;
        Ok(Self(date))
    }
}
