//! One executable workflow against real HTTP, Parquet and PostgreSQL boundaries.

use std::{collections::BTreeMap, fs::{self, File}, path::{Path, PathBuf}, process::Output, time::Duration};
use arrow_array::{Array, Date32Array, Int16Array, Int32Array, RecordBatch, StringArray};
use axum::{Json, Router, extract::{RawQuery, State}, http::StatusCode, response::{IntoResponse, Response}, routing::get};
use chrono::{DateTime, NaiveDate, Utc};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use serde_json::{Value, json};
use sqlx::{ConnectOptions, PgPool, postgres::PgConnectOptions};
use tokio::{net::TcpListener, process::Command, task::JoinHandle};
use uuid::Uuid;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Fixture { Original, Corrected, SourceFailure }

struct FixtureServer { url: String, task: JoinHandle<()> }
impl Drop for FixtureServer { fn drop(&mut self) { self.task.abort(); } }
impl FixtureServer {
    async fn start(mode: Fixture) -> Self {
        let app = Router::new().route("/api/Members/Search", get(search)).route("/api/Members/History", get(histories)).with_state(mode);
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let url = format!("http://{}", listener.local_addr().unwrap());
        let task = tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });
        Self { url, task }
    }
    async fn stop(&mut self) { self.task.abort(); let _ = (&mut self.task).await; }
}
fn profile(id: i32, mode: Fixture, current_search: bool) -> Value {
    let name = if current_search { format!("Current search profile {id}") }
        else if id == 1 && mode == Fixture::Corrected { "Corrected Member".into() }
        else { format!("Historical Member {id}") };
    json!({"value": {"id": id, "nameDisplayAs": name,
        "latestParty": if id == 4 { Value::Null } else { json!({"id": 15, "name": if id == 2 && mode == Fixture::Corrected { "Corrected Party" } else { "Party" }}) },
        "latestHouseMembership": {"house": if matches!(id, 2 | 4) { 2 } else { 1 }, "membershipFrom": if id == 4 { Value::Null } else { json!(" Source location ") }}
    }})
}
async fn search(State(mode): State<Fixture>, RawQuery(query): RawQuery) -> Response {
    let url = reqwest::Url::parse(&format!("http://fixture/?{}", query.unwrap())).unwrap();
    let params: BTreeMap<_, _> = url.query_pairs().into_owned().collect();
    assert_eq!(params["take"], "20");
    let offset: usize = params["skip"].parse().unwrap();
    let current = params.contains_key("IsCurrentMember");
    let ids = if current {
        assert_eq!(params["IsCurrentMember"], "true");
        assert_eq!(params["House"], "1");
        vec![1, 1, 3] // Identical repeated profiles within this stream.
    } else {
        assert!(!params.contains_key("House"));
        assert_eq!(params["MembershipInDateRange.WasMemberOfHouse"], "1");
        assert_eq!(params["MembershipInDateRange.WasMemberOnOrAfter"], "2024-07-04");
        NaiveDate::parse_from_str(&params["MembershipInDateRange.WasMemberOnOrBefore"], "%Y-%m-%d").unwrap();
        if mode == Fixture::SourceFailure && offset > 0 {
            return (StatusCode::SERVICE_UNAVAILABLE, [("Retry-After", "0")], "fixture unavailable").into_response();
        }
        if mode == Fixture::Corrected { vec![1, 2, 1, 3, 4] } else { vec![1, 2, 1, 3, 4, 5] }
    };
    let items: Vec<_> = ids.iter().skip(offset).take(2).map(|id| profile(*id, mode, current)).collect();
    // Later metadata shrinks the advertised total; clients must re-read it.
    Json(json!({"items": items, "totalResults": if offset == 0 { 9 } else { ids.len() }, "skip": offset, "take": 20})).into_response()
}
fn membership(house: i16, start: &str, end: Option<&str>) -> Value {
    json!({"house": house, "membershipStartDate": start, "membershipEndDate": end})
}
async fn histories(State(mode): State<Fixture>, RawQuery(query): RawQuery) -> Json<Value> {
    let url = reqwest::Url::parse(&format!("http://fixture/?{}", query.unwrap())).unwrap();
    let values: Vec<_> = url.query_pairs().map(|(key, id)| {
        assert_eq!(key, "ids");
        let id: i32 = id.parse().unwrap();
        let periods = match id {
            1 => vec![membership(1, "2020-01-01T23:30:00-02:00", None), membership(1, "2020-01-01T23:30:00-02:00", None)],
            2 => vec![membership(1, "2020-01-01", Some(if mode == Fixture::Corrected { "2025-02-02" } else { "2025-01-31T23:30:00-02:00" })), membership(2, "2025-02-03", None)],
            3 => vec![membership(1, "2020-01-01", Some("2024-12-01")), membership(1, if mode == Fixture::Corrected { "2025-02-05" } else { "2025-02-01" }, None)],
            4 => vec![membership(1, "2020-01-01", Some("2024-07-04")), membership(2, "2024-07-05", None)],
            5 => vec![membership(1, "2020-01-01", Some("2024-08-01"))],
            _ => panic!("unexpected member ID {id}"),
        };
        json!({"value": {"id": id, "houseMembershipHistory": periods}})
    }).collect();
    Json(json!(values))
}
async fn command(config: &Path, operation: &str, capture_id: Option<&str>) -> Output {
    let mut command = Command::new(env!("CARGO_BIN_EXE_exposed"));
    command.args(["data", operation, "members"]).arg(config).env_remove("DATABASE_URL");
    if let Some(id) = capture_id { command.arg(id); }
    tokio::time::timeout(Duration::from_secs(40), command.kill_on_drop(true).output()).await.expect("CLI timed out").unwrap()
}
fn success(output: &Output) -> Value {
    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    let summary: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(summary["status"], "succeeded");
    summary
}
fn write_fetch_config(root: &Path, server: &FixtureServer) -> PathBuf {
    let config = root.join("fetch.yaml");
    fs::write(&config, format!("data_root: {}\nterm_start: '2024-07-04'\nmembers_api_url: {}\n", root.display(), server.url)).unwrap();
    config
}
fn parquet(path: &Path) -> RecordBatch {
    let mut batches = ParquetRecordBatchReaderBuilder::try_new(File::open(path).unwrap()).unwrap().build().unwrap();
    let batch = batches.next().unwrap().unwrap();
    assert!(batches.next().is_none());
    batch
}
fn column<'a, T: Array + 'static>(batch: &'a RecordBatch, name: &str) -> &'a T {
    batch.column_by_name(name).unwrap().as_any().downcast_ref().unwrap()
}
fn capture_files(path: &Path) -> BTreeMap<String, Vec<u8>> {
    fs::read_dir(path).unwrap().map(|entry| {
        let entry = entry.unwrap();
        (entry.file_name().to_str().unwrap().into(), fs::read(entry.path()).unwrap())
    }).collect()
}
async fn database_state(pool: &PgPool) -> Value {
    sqlx::query_scalar("SELECT jsonb_build_object(
        'terms', (SELECT coalesce(jsonb_agg(t ORDER BY term_start), '[]') FROM exposed.parliament_terms t),
        'members', (SELECT coalesce(jsonb_agg(m ORDER BY parliament_member_id), '[]') FROM exposed.members m),
