    let history = parquet(&path.join("house_memberships.parquet"));
    assert_eq!(history.num_rows(), 9);
    assert_eq!(column::<Date32Array>(&history, "source_start_date").value_as_date(0).unwrap().to_string(), "2020-01-01");
    assert_eq!(column::<Date32Array>(&history, "source_end_date").value_as_date(2).unwrap().to_string(), "2025-01-31");
    assert!(column::<Date32Array>(&history, "source_end_date").is_null(0));
    assert_eq!(database_state(pool).await, empty_database);

