    assert_eq!(loaded["observation_date"], manifest["observation_date"]);
    assert_eq!(loaded["term_start"], "2024-07-04");
    assert_eq!(loaded["summary"], json!({"members": 4, "current_commons": 2, "former_commons": 2, "inserted": 4, "updated": 0, "unchanged": 0, "service_periods": 5, "excluded_candidates": 1}));
