    let corrected_load = success(&command(&load_config, "load", Some(corrected_id)).await);
    assert_eq!(corrected_load["summary"], json!({"members": 3, "current_commons": 2, "former_commons": 1, "inserted": 0, "updated": 2, "unchanged": 1, "service_periods": 4, "excluded_candidates": 1}));
