    assert_eq!(member(&after_correction, 2)["party_name"], "Corrected Party");
    for source_id in [1, 2, 3, 5] { assert_eq!(member(&after_correction, source_id)["id"], member(&first, source_id)["id"]); }
    assert_eq!(services(&after_correction, 1), services(&first, 1));
    assert_eq!(services(&after_correction, 2)[0]["id"], services(&first, 2)[0]["id"]);
    assert_eq!(services(&after_correction, 2)[0]["served_until"], "2025-02-02T00:00:00+00:00");
    assert_eq!(services(&after_correction, 3)[0], services(&first, 3)[0]);
    assert_ne!(services(&after_correction, 3)[1]["id"], services(&first, 3)[1]["id"]);
    assert_eq!(services(&after_correction, 3)[1]["source_start_date"], "2025-02-05T00:00:00+00:00");
    assert_eq!(member(&after_correction, 5), member(&first, 5));
    assert_eq!(services(&after_correction, 5), services(&first, 5));
    assert_eq!(after_correction["declarations"], before_repeat["declarations"]);
    assert_eq!(after_correction["terms"], before_repeat["terms"]);
