                || history.house_memberships.is_empty()
            {
                return Err(invalid(format!(
                    "member {id}: duplicate, unexpected or empty history"
                )));
            }
        }
        if histories != candidates {
            return Err(invalid("histories do not contain all requested member IDs"));
