//! Captured member observations and the rules for interpreting Commons service.

use std::{
    collections::{BTreeMap, BTreeSet},
    fmt,
    str::FromStr,
};

use chrono::{DateTime, NaiveDate, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use super::entity_ingestion::EntityIngestionError;

/// Identity of an immutable capture, ordered by `UUIDv7` creation time.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(try_from = "Uuid", into = "Uuid")]
pub struct CaptureId(Uuid);

impl CaptureId {
    /// Allocate an identity at the beginning of a fetch attempt.
    #[must_use]
    pub fn new() -> Self {
        Self(Uuid::now_v7())
    }
}

impl Default for CaptureId {
    fn default() -> Self {
        Self::new()
    }
}
impl From<CaptureId> for Uuid {
    fn from(id: CaptureId) -> Self {
        id.0
    }
}
impl TryFrom<Uuid> for CaptureId {
    type Error = EntityIngestionError;
    fn try_from(id: Uuid) -> Result<Self, Self::Error> {
        if id.get_version_num() != 7 || id.get_variant() != uuid::Variant::RFC4122 {
            return Err(invalid("capture ID must be a UUIDv7"));
        }
        Ok(Self(id))
    }
}
impl FromStr for CaptureId {
    type Err = EntityIngestionError;
    fn from_str(value: &str) -> Result<Self, Self::Err> {
        Uuid::parse_str(value)
            .map_err(|_| invalid("capture ID must be a UUIDv7"))?
            .try_into()
    }
}
impl fmt::Display for CaptureId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

/// Context fixed when acquisition begins, retained for offline interpretation.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct CaptureContext {
    /// `UUIDv7` allocated for this attempt.
    pub capture_id: CaptureId,
    /// Beginning of the configured Parliament.
    pub term_start: NaiveDate,
    /// Calendar date in Europe/London at the start of acquisition.
    pub observation_date: NaiveDate,
    /// UTC instant at the start of acquisition.
    pub started_at: DateTime<Utc>,
}

/// Historical candidate profile; optional source values remain absent.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MemberProfile {
    /// Parliament's numeric identity.
    pub parliament_member_id: i32,
    /// Source display name, without normalization.
    pub name: String,
    /// Latest party identity when supplied.
    pub party_id: Option<i32>,
    /// Latest party name when supplied.
    pub party_name: Option<String>,
    /// Latest House, which may be Lords for a former MP.
    pub latest_house: i16,
    /// Latest membership location when supplied.
    pub latest_membership_from: Option<String>,
}

/// One source House membership, before any term clipping or deduplication.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct HouseMembership {
    /// Commons (1) or Lords (2).
    pub house: i16,
    /// Source calendar start date.
    pub start_date: NaiveDate,
    /// Date service ceased, if supplied.
    pub end_date: Option<NaiveDate>,
}

/// A returned history, retaining its identity for completeness checks.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MemberHistory {
    /// Parliament's numeric identity.
    pub parliament_member_id: i32,
    /// All returned House membership periods, including identical repeats.
    pub house_memberships: Vec<HouseMembership>,
}

/// Complete source observations, with no database identities or derived service.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MemberObservations {
    /// Distinct historical candidate profiles.
    pub profiles: Vec<MemberProfile>,
    /// Distinct identities observed in the current Commons search.
    pub current_commons: Vec<i32>,
    /// Exactly one history for every candidate.
    pub histories: Vec<MemberHistory>,
}

/// A member capture ready to persist or interpret.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MemberCapture {
    /// Original term and observation context.
    pub context: CaptureContext,
    /// Complete source observations.
    pub observations: MemberObservations,
}

/// Row counts for the three raw datasets.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct CaptureCounts {
    /// Historical candidate profiles.
    pub profiles: usize,
    /// Current Commons identities.
    pub current_commons: usize,
    /// All source House membership periods.
    pub house_memberships: usize,
}

impl MemberObservations {
    /// Counts before service filtering and deduplication.
    #[must_use]
    pub fn counts(&self) -> CaptureCounts {
        CaptureCounts {
            profiles: self.profiles.len(),
            current_commons: self.current_commons.len(),
            house_memberships: self
                .histories
                .iter()
                .map(|h| h.house_memberships.len())
                .sum(),
        }
    }

    /// Check identities and completeness without applying service rules.
    ///
    /// # Errors
    /// Rejects duplicate, invalid, extra or missing source identities and empty histories.
    pub fn validate(&self) -> Result<(), EntityIngestionError> {
        let mut candidates = BTreeSet::new();
        for profile in &self.profiles {
            let id = profile.parliament_member_id;
            if id <= 0 || !candidates.insert(id) {
                return Err(invalid(format!(
                    "member {id}: invalid or duplicate profile identity"
                )));
            }
        }
        let mut current = BTreeSet::new();
        for id in &self.current_commons {
            if !current.insert(*id) || !candidates.contains(id) {
                return Err(invalid(format!(
                    "current Commons member {id}: duplicate or missing from historical candidates"
                )));
            }
        }
        let mut histories = BTreeSet::new();
        for history in &self.histories {
            let id = history.parliament_member_id;
            if !histories.insert(id)
                || !candidates.contains(&id)
                || history.house_memberships.is_empty()
            {
                return Err(invalid(format!(
                    "member {id}: duplicate, unexpected or empty history"
                )));
            }
        }
        if histories != candidates {
            return Err(invalid("histories do not contain all requested member IDs"));
        }
        Ok(())
    }
}

/// Validated member fields for PostgreSQL.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MemberRecord {
    /// Parliament's numeric identity, used for reconciliation.
    pub parliament_member_id: i32,
    /// Source display name.
    pub name: String,
    /// Required latest party identity.
    pub party_id: i32,
    /// Required latest party name.
    pub party_name: String,
    /// Latest House from the historical candidate profile.
    pub latest_house: i16,
    /// Required latest membership location.
    pub latest_membership_from: String,
    /// Status from the captured current Commons search.
    pub is_current_commons: bool,
}

/// A distinct Commons interval in the configured term.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ServicePeriod {
    /// Source start date, the stable identity of an interval.
    pub source_start_date: NaiveDate,
    /// Source end date, also used as served-until.
    pub source_end_date: Option<NaiveDate>,
    /// Later of source start and term start.
    pub served_from: NaiveDate,
}

/// One accepted profile and its complete replacement set of term service.
#[derive(Clone, Debug)]
pub struct MemberImport {
    /// Validated profile to reconcile.
    pub member: MemberRecord,
    /// Distinct and non-overlapping Commons periods.
    pub periods: Vec<ServicePeriod>,
}

/// Entire refresh validated before storage receives it.
#[derive(Clone, Debug)]
pub struct MemberRefresh {
    /// Captured Parliament start.
    pub term_start: NaiveDate,
    /// Eligible members; absent members must remain untouched.
    pub members: Vec<MemberImport>,
    /// Candidates with no qualifying Commons service.
    pub excluded_candidates: usize,
}

/// Committed profile outcomes and cohort/service counts.
#[derive(Clone, Debug, Default, Serialize)]
pub struct MemberImportSummary {
    /// Number of eligible members processed.
    pub members: usize,
    /// Current Commons members.
    pub current_commons: usize,
    /// Former Commons members.
    pub former_commons: usize,
    /// Newly inserted profiles.
    pub inserted: usize,
    /// Changed profiles.
    pub updated: usize,
    /// Identical profiles.
    pub unchanged: usize,
    /// Distinct term service periods reconciled.
    pub service_periods: usize,
    /// Candidates excluded for lack of term service.
    pub excluded_candidates: usize,
}

impl MemberCapture {
    /// Interpret all observations before making any database writes.
    ///
    /// # Errors
    /// Rejects incomplete captures, invalid fields and inconsistent Commons service.
    pub fn prepare_refresh(&self) -> Result<MemberRefresh, EntityIngestionError> {
        self.observations.validate()?;
        let term_start = self.context.term_start;
        let as_of = self.context.observation_date;
        if term_start > as_of {
            return Err(invalid("term start is after observation date"));
        }
        let current: BTreeSet<_> = self.observations.current_commons.iter().copied().collect();
        let histories: BTreeMap<_, _> = self
            .observations
            .histories
            .iter()
            .map(|h| (h.parliament_member_id, h))
            .collect();
        let mut refresh = MemberRefresh {
            term_start,
            members: Vec::new(),
            excluded_candidates: 0,
        };
        for profile in &self.observations.profiles {
            let id = profile.parliament_member_id;
            let is_current = current.contains(&id);
            let periods = service_periods(histories[&id], term_start, as_of, is_current)?;
            if periods.is_empty() {
                refresh.excluded_candidates += 1;
                continue;
            }
            let member = profile.for_database(is_current)?;
            refresh.members.push(MemberImport { member, periods });
        }
        if refresh.members.is_empty() {
            return Err(invalid(
                "no Commons service was found for the configured term",
            ));
        }
        Ok(refresh)
    }
}

impl MemberProfile {
    fn for_database(&self, is_current_commons: bool) -> Result<MemberRecord, EntityIngestionError> {
        let id = self.parliament_member_id;
        let required =
            |field: &str| invalid(format!("member {id}: {field} is required for PostgreSQL"));
        if self.name.trim().is_empty() {
            return Err(required("name"));
        }
        if !matches!(self.latest_house, 1 | 2) || (is_current_commons && self.latest_house != 1) {
            return Err(invalid(format!("member {id}: inconsistent latest House")));
        }
        Ok(MemberRecord {
            parliament_member_id: id,
            name: self.name.clone(),
            party_id: self
                .party_id
                .filter(|id| *id > 0)
                .ok_or_else(|| required("party_id"))?,
            party_name: self
                .party_name
                .clone()
                .ok_or_else(|| required("party_name"))?,
            latest_house: self.latest_house,
            latest_membership_from: self
                .latest_membership_from
                .clone()
                .ok_or_else(|| required("latest_membership_from"))?,
            is_current_commons,
        })
    }
}

fn service_periods(
    history: &MemberHistory,
    term_start: NaiveDate,
    as_of: NaiveDate,
    current: bool,
) -> Result<Vec<ServicePeriod>, EntityIngestionError> {
    let id = history.parliament_member_id;
    let mut memberships = BTreeSet::new();
    for membership in &history.house_memberships {
        if !matches!(membership.house, 1 | 2)
            || membership
                .end_date
                .is_some_and(|end| end < membership.start_date)
        {
            return Err(invalid(format!(
                "member {id}: invalid House or membership date ordering"
            )));
        }
        if membership.house == 1
            && membership.start_date <= as_of
            && membership.end_date.is_none_or(|end| end > term_start)
        {
            memberships.insert(membership);
        }
    }
    let periods: Vec<_> = memberships
        .into_iter()
        .map(|m| ServicePeriod {
            source_start_date: m.start_date,
            source_end_date: m.end_date,
            served_from: m.start_date.max(term_start),
        })
        .collect();
    for pair in periods.windows(2) {
        if pair[0].source_start_date == pair[1].source_start_date {
            return Err(invalid(format!("member {id}: conflicting service starts")));
        }
        if pair[0]
            .source_end_date
            .is_none_or(|end| pair[1].served_from < end)
        {
            return Err(invalid(format!("member {id}: overlapping service periods")));
        }
    }
    let active = periods
        .iter()
        .any(|p| p.source_end_date.is_none_or(|end| end > as_of));
    if active != current {
        return Err(invalid(format!(
            "member {id}: history disagrees with current Commons search"
        )));
    }
    Ok(periods)
}

pub(crate) fn invalid(message: impl Into<String>) -> EntityIngestionError {
    EntityIngestionError::DataError(message.into())
}
//! Schema-v1 Parquet translation. Domain rules are applied only after reading.
use crate::domain::models::member_ingestion::{
    HouseMembership, MemberHistory, MemberObservations, MemberProfile,
};
use anyhow::{Context, ensure};
use arrow_array::{Array, ArrayRef, Date32Array, Int16Array, Int32Array, RecordBatch, StringArray};
use arrow_schema::{DataType, Field, Schema, SchemaRef};
use chrono::NaiveDate;
use parquet::{
    arrow::{ArrowWriter, arrow_reader::ParquetRecordBatchReaderBuilder},
    basic::Compression,
    file::properties::WriterProperties,
};
use std::{collections::BTreeMap, fs::File, path::Path, sync::Arc};

fn profiles_schema() -> SchemaRef {
    Arc::new(Schema::new(vec![
        Field::new("parliament_member_id", DataType::Int32, false),
        Field::new("name", DataType::Utf8, false),
        Field::new("party_id", DataType::Int32, true),
        Field::new("party_name", DataType::Utf8, true),
        Field::new("latest_house", DataType::Int16, false),
        Field::new("latest_membership_from", DataType::Utf8, true),
    ]))
}
fn current_schema() -> SchemaRef {
    Arc::new(Schema::new(vec![Field::new(
        "parliament_member_id",
        DataType::Int32,
        false,
    )]))
}
fn memberships_schema() -> SchemaRef {
    Arc::new(Schema::new(vec![
        Field::new("parliament_member_id", DataType::Int32, false),
        Field::new("house", DataType::Int16, false),
        Field::new("source_start_date", DataType::Date32, false),
        Field::new("source_end_date", DataType::Date32, true),
    ]))
}

pub(super) fn write(path: &Path, data: &MemberObservations) -> anyhow::Result<()> {
    let profiles = &data.profiles;
    write_batch(
        &path.join("profiles.parquet"),
        profiles_schema(),
        vec![
            Arc::new(Int32Array::from_iter_values(
                profiles.iter().map(|p| p.parliament_member_id),
            )),
            Arc::new(StringArray::from_iter_values(
                profiles.iter().map(|p| &p.name),
            )),
            Arc::new(Int32Array::from_iter(profiles.iter().map(|p| p.party_id))),
            Arc::new(StringArray::from_iter(
                profiles.iter().map(|p| p.party_name.as_deref()),
            )),
            Arc::new(Int16Array::from_iter_values(
                profiles.iter().map(|p| p.latest_house),
            )),
            Arc::new(StringArray::from_iter(
                profiles.iter().map(|p| p.latest_membership_from.as_deref()),
            )),
        ],
    )?;
    write_batch(
        &path.join("current_commons.parquet"),
        current_schema(),
        vec![Arc::new(Int32Array::from(data.current_commons.clone()))],
    )?;
    let rows: Vec<_> = data
        .histories
        .iter()
        .flat_map(|h| {
            h.house_memberships
                .iter()
                .map(move |m| (h.parliament_member_id, m))
        })
        .collect();
    write_batch(
        &path.join("house_memberships.parquet"),
        memberships_schema(),
        vec![
            Arc::new(Int32Array::from_iter_values(rows.iter().map(|(id, _)| *id))),
            Arc::new(Int16Array::from_iter_values(
                rows.iter().map(|(_, m)| m.house),
            )),
            Arc::new(Date32Array::from_iter_values(
                rows.iter().map(|(_, m)| m.start_date.to_epoch_days()),
            )),
            Arc::new(Date32Array::from_iter(
                rows.iter()
                    .map(|(_, m)| m.end_date.map(|d| d.to_epoch_days())),
            )),
        ],
    )?;
    Ok(())
}
fn write_batch(path: &Path, schema: SchemaRef, columns: Vec<ArrayRef>) -> anyhow::Result<()> {
    let batch = RecordBatch::try_new(schema.clone(), columns)?;
    let file = File::create_new(path).with_context(|| format!("create {}", path.display()))?;
    let properties = WriterProperties::builder()
        .set_compression(Compression::SNAPPY)
        .build();
    let mut writer = ArrowWriter::try_new(&file, schema, Some(properties))?;
    writer.write(&batch)?;
    writer.close()?;
    file.sync_all()?;
    Ok(())
}

pub(super) fn read(path: &Path) -> anyhow::Result<MemberObservations> {
    let mut profiles = Vec::new();
    for batch in read_batches(&path.join("profiles.parquet"), &profiles_schema())? {
        let ids: &Int32Array = column(&batch, 0)?;
        let names: &StringArray = column(&batch, 1)?;
        let parties: &Int32Array = column(&batch, 2)?;
        let party_names: &StringArray = column(&batch, 3)?;
        let houses: &Int16Array = column(&batch, 4)?;
        let locations: &StringArray = column(&batch, 5)?;
        for row in 0..batch.num_rows() {
            profiles.push(MemberProfile {
                parliament_member_id: ids.value(row),
                name: names.value(row).into(),
                party_id: (!parties.is_null(row)).then(|| parties.value(row)),
                party_name: (!party_names.is_null(row)).then(|| party_names.value(row).into()),
                latest_house: houses.value(row),
                latest_membership_from: (!locations.is_null(row))
                    .then(|| locations.value(row).into()),
            });
        }
    }
    let mut current_commons = Vec::new();
    for batch in read_batches(&path.join("current_commons.parquet"), &current_schema())? {
        let ids: &Int32Array = column(&batch, 0)?;
        current_commons.extend(ids.values());
    }
    let mut histories: BTreeMap<i32, Vec<HouseMembership>> = BTreeMap::new();
    for batch in read_batches(
        &path.join("house_memberships.parquet"),
        &memberships_schema(),
    )? {
        let ids: &Int32Array = column(&batch, 0)?;
        let houses: &Int16Array = column(&batch, 1)?;
        let starts: &Date32Array = column(&batch, 2)?;
        let ends: &Date32Array = column(&batch, 3)?;
        for row in 0..batch.num_rows() {
            let id = ids.value(row);
            let date = |value| {
                NaiveDate::from_epoch_days(value)
                    .with_context(|| format!("member {id}: invalid source calendar date"))
            };
            histories.entry(id).or_default().push(HouseMembership {
                house: houses.value(row),
                start_date: date(starts.value(row))?,
                end_date: if ends.is_null(row) {
                    None
                } else {
                    Some(date(ends.value(row))?)
                },
            });
        }
    }
    Ok(MemberObservations {
        profiles,
        current_commons,
        histories: histories
            .into_iter()
            .map(|(parliament_member_id, house_memberships)| MemberHistory {
                parliament_member_id,
                house_memberships,
            })
            .collect(),
    })
}
fn read_batches(path: &Path, schema: &SchemaRef) -> anyhow::Result<Vec<RecordBatch>> {
    let result = (|| {
        let builder = ParquetRecordBatchReaderBuilder::try_new(File::open(path)?)?;
        ensure!(
            builder.schema().fields() == schema.fields(),
            "Parquet types, fields or nullability do not match schema v1"
        );
        let batches = builder.build()?.collect::<Result<Vec<_>, _>>()?;
        for batch in &batches {
            for (field, column) in schema.fields().iter().zip(batch.columns()) {
                ensure!(
                    field.is_nullable() || column.null_count() == 0,
                    "required column {} contains nulls",
                    field.name()
                );
            }
        }
        Ok(batches)
    })();
    result.with_context(|| format!("read {}", path.display()))
}
fn column<T: Array + 'static>(batch: &RecordBatch, index: usize) -> anyhow::Result<&T> {
    batch
        .column(index)
        .as_any()
        .downcast_ref()
        .context("unexpected Parquet column type")
}
//! Immutable member captures, staged and published on the same filesystem.
use super::member_parquet;
use crate::domain::{
    models::member_ingestion::{CaptureContext, CaptureCounts, CaptureId, MemberCapture},
    repositories::entity_ingestion_pipline::{EntityIngestionStorage, EntitySearchPipelineError},
};
use anyhow::{Context, ensure};
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::{
    fs::{self, File},
    path::{Path, PathBuf},
};

/// Local data root with captures at raw/members/<UUIDv7>.
#[derive(Clone)]
pub struct ExposedDataPipeline {
    root: PathBuf,
}
impl ExposedDataPipeline {
    /// Use this data root without creating files until Fetch is finalized.
    #[must_use]
    pub const fn new(root: PathBuf) -> Self {
        Self { root }
    }

    fn read_at(path: &Path, id: CaptureId) -> anyhow::Result<MemberCapture> {
        let manifest: Manifest = serde_json::from_reader(
            File::open(path.join("manifest.json")).context("missing completed manifest")?,
        )
        .context("invalid manifest")?;
        ensure!(
            manifest.schema_version == 1,
            "unsupported member schema version {}",
            manifest.schema_version
        );
        ensure!(
            manifest.context.capture_id == id,
            "manifest capture identity does not match {id}"
        );
        ensure!(
            manifest.completed_at >= manifest.context.started_at,
            "completion timestamp precedes capture start"
        );
        ensure!(
            manifest.context.term_start <= manifest.context.observation_date,
            "term starts after observation date"
        );
        ensure!(
            manifest.datasets == DatasetFiles::default(),
            "manifest must identify all three schema-v1 datasets"
        );
        let observations = member_parquet::read(path)?;
        ensure!(
            observations.counts() == manifest.counts,
            "dataset row counts disagree with manifest"
        );
        observations.validate()?;
        Ok(MemberCapture {
            context: manifest.context,
            observations,
        })
    }

    fn stage(&self, capture: &MemberCapture) -> anyhow::Result<PendingCapture> {
        capture.observations.validate()?;
        let id = capture.context.capture_id;
        let parent = self.root.join("raw/members");
        fs::create_dir_all(&parent)?;
        let destination = parent.join(id.to_string());
        ensure!(
            !destination.exists(),
            "completed capture {id} already exists"
        );
        let staging = tempfile::Builder::new()
            .prefix(&format!(".staging-{id}-"))
            .tempdir_in(&parent)?;
        member_parquet::write(staging.path(), &capture.observations)?;
        let manifest = Manifest {
            schema_version: 1,
            context: capture.context.clone(),
            completed_at: Utc::now(),
            datasets: DatasetFiles::default(),
            counts: capture.observations.counts(),
        };
        let file = File::create_new(staging.path().join("manifest.json"))?;
        serde_json::to_writer_pretty(&file, &manifest)?;
        file.sync_all()?;
        let verified = Self::read_at(staging.path(), id)?;
        ensure!(
            verified == *capture,
            "capture round-trip verification failed"
        );
        Ok(PendingCapture {
            staging,
            destination,
            id,
        })
    }
}
impl EntityIngestionStorage for ExposedDataPipeline {
    async fn read_member_capture(
        &self,
        id: CaptureId,
    ) -> Result<MemberCapture, EntitySearchPipelineError> {
        let path = self.root.join("raw/members").join(id.to_string());
        tokio::task::spawn_blocking(move || Self::read_at(&path, id))
            .await
            .map_err(|error| EntitySearchPipelineError(format!("read capture {id}: {error}")))?
            .map_err(|error| EntitySearchPipelineError(format!("capture {id}: {error:#}")))
    }
    async fn write_member_capture(
        &self,
        capture: MemberCapture,
    ) -> Result<CaptureId, EntitySearchPipelineError> {
        let id = capture.context.capture_id;
        let storage = self.clone();
        let pending = tokio::task::spawn_blocking(move || storage.stage(&capture))
            .await
            .map_err(|error| EntitySearchPipelineError(format!("stage capture {id}: {error}")))?
            .map_err(|error| EntitySearchPipelineError(format!("capture {id}: {error:#}")))?;
        pending
            .publish()
            .map_err(|error| EntitySearchPipelineError(format!("publish capture {id}: {error:#}")))
    }
}

struct PendingCapture {
    staging: tempfile::TempDir,
    destination: PathBuf,
    id: CaptureId,
}

impl PendingCapture {
    fn publish(self) -> std::io::Result<CaptureId> {
        // Dropping a cancelled staging task removes its temporary directory.
        // No await or fallible work follows atomic publication.
        fs::rename(self.staging.path(), &self.destination)?;
        Ok(self.id)
    }
}

#[derive(Serialize, Deserialize)]
struct Manifest {
    schema_version: u32,
    #[serde(flatten)]
    context: CaptureContext,
    completed_at: DateTime<Utc>,
    datasets: DatasetFiles,
    counts: CaptureCounts,
}
#[derive(Serialize, Deserialize, PartialEq, Eq)]
struct DatasetFiles {
    profiles: String,
    current_commons: String,
    house_memberships: String,
}
impl Default for DatasetFiles {
    fn default() -> Self {
        Self {
            profiles: "profiles.parquet".into(),
            current_commons: "current_commons.parquet".into(),
            house_memberships: "house_memberships.parquet".into(),
        }
    }
}
//! Sequential Members API requests, typed decoding and bounded retries.
use crate::domain::{
    models::member_ingestion::{HouseMembership, MemberHistory, MemberProfile},
    repositories::parliament_api::{ParliamentApi, ParliamentApiError},
};
use chrono::{DateTime, NaiveDate, NaiveDateTime};
use reqwest::{Client, StatusCode, Url};
use serde::{Deserialize, de::DeserializeOwned};
use serde_json::Value;
use std::{
    fmt::Display,
    time::{Duration, SystemTime},
};

/// Production HTTP source for the Commons cohort.
#[derive(Clone)]
pub struct MembersApi {
    client: Client,
    base_url: Url,
}
impl MembersApi {
    /// Build an HTTP client without issuing requests.
    ///
    /// # Errors
    /// Rejects invalid URLs or HTTP client configuration.
    pub fn new(base_url: &str) -> Result<Self, ParliamentApiError> {
        let base_url = Url::parse(base_url).map_err(|_| failure("invalid Members API URL"))?;
        if !matches!(base_url.scheme(), "http" | "https")
            || base_url.host_str().is_none()
            || !base_url.username().is_empty()
            || base_url.password().is_some()
        {
            return Err(failure(
                "Members API URL must be an HTTP(S) URL without credentials",
            ));
        }
        let client = Client::builder()
            .connect_timeout(Duration::from_secs(10))
            .timeout(Duration::from_secs(30))
            .build()
            .map_err(failure)?;
        Ok(Self { client, base_url })
    }

    async fn get(
        &self,
        path: &str,
        params: &[(&str, String)],
    ) -> Result<Vec<u8>, ParliamentApiError> {
        let mut url = self.base_url.join(path).map_err(failure)?;
        url.query_pairs_mut()
            .extend_pairs(params.iter().map(|(key, value)| (*key, value.as_str())));
        // Request context contains source filters/IDs, never connection credentials.
        let context = format!("{path}?{}", url.query().unwrap_or_default());
        for attempt in 0..4 {
            tokio::time::sleep(Duration::from_millis(200)).await;
            let mut delay = Duration::from_secs(1 << attempt);
            let problem = match self.client.get(url.clone()).send().await {
                Ok(response) => {
                    let status = response.status();
                    if status == StatusCode::OK {
                        match response.bytes().await {
                            Ok(bytes) => return Ok(bytes.to_vec()),
                            Err(error) => format!("response transport failure: {error}"),
                        }
                    } else {
                        if status != StatusCode::TOO_MANY_REQUESTS && !status.is_server_error() {
                            return Err(failure(format!("{context}: HTTP {status}")));
                        }
                        if let Some(header) = response
                            .headers()
                            .get(reqwest::header::RETRY_AFTER)
                            .and_then(|h| h.to_str().ok())
                        {
                            delay = retry_delay(header).unwrap_or(delay);
                        }
                        format!("HTTP {status}")
                    }
                }
                Err(error) => format!("transport failure: {error}"),
            };
            if attempt == 3 {
                return Err(failure(format!("{context}: {problem} after four attempts")));
            }
            eprintln!("{context}: {problem}; retry {}/4", attempt + 2);
            tokio::time::sleep(delay.min(Duration::from_secs(30))).await;
        }
        unreachable!("four attempts always return success or failure")
    }

    async fn search(
        &self,
        filters: Vec<(&str, String)>,
    ) -> Result<Vec<MemberProfile>, ParliamentApiError> {
        let mut profiles = Vec::new();
        let mut offset = 0;
        loop {
            let mut params = filters.clone();
            params.extend([("skip", offset.to_string()), ("take", "20".to_owned())]);
            let bytes = self.get("/api/Members/Search", &params).await?;
            let context = format!("/api/Members/Search {params:?}");
            let page: SearchPage = decode(&bytes, &context)?;
            if page.skip != offset {
                return Err(failure(format!(
                    "{context}: response skip {} does not match request {offset}",
                    page.skip
                )));
            }
            if page.items.is_empty() && offset < page.total_results {
                return Err(failure(format!(
                    "{context}: premature empty page before total {}",
                    page.total_results
                )));
            }
            offset = offset
                .checked_add(page.items.len())
                .ok_or_else(|| failure("search pagination overflow"))?;
            for value in page.items {
                let item: Item<Profile> = decode_item(value, &context)?;
                profiles.push(MemberProfile {
                    parliament_member_id: item.value.id,
                    name: item.value.name_display_as,
                    party_id: item.value.latest_party.as_ref().and_then(|p| p.id),
                    party_name: item.value.latest_party.and_then(|p| p.name),
                    latest_house: item.value.latest_house_membership.house,
                    latest_membership_from: item.value.latest_house_membership.membership_from,
                });
            }
            if offset >= page.total_results {
                return Ok(profiles);
            }
        }
    }
}

impl ParliamentApi for MembersApi {
    async fn current_commons(&self) -> Result<Vec<MemberProfile>, ParliamentApiError> {
        self.search(vec![
            ("House", "1".into()),
            ("IsCurrentMember", "true".into()),
        ])
        .await
    }
    async fn commons_candidates(
        &self,
        term_start: NaiveDate,
        observation_date: NaiveDate,
    ) -> Result<Vec<MemberProfile>, ParliamentApiError> {
        self.search(vec![
            (
                "MembershipInDateRange.WasMemberOnOrAfter",
                term_start.to_string(),
            ),
            (
                "MembershipInDateRange.WasMemberOnOrBefore",
                observation_date.to_string(),
            ),
            ("MembershipInDateRange.WasMemberOfHouse", "1".into()),
        ])
        .await
    }
    async fn member_histories(
        &self,
        member_ids: &[i32],
    ) -> Result<Vec<MemberHistory>, ParliamentApiError> {
        if member_ids.is_empty() || member_ids.len() > 100 {
            return Err(failure("history requests require 1–100 member IDs"));
        }
        let params: Vec<_> = member_ids
            .iter()
            .map(|id| ("ids", id.to_string()))
            .collect();
        let bytes = self.get("/api/Members/History", &params).await?;
        let context = format!("/api/Members/History {member_ids:?}");
        let values: Vec<Value> = decode(&bytes, &context)?;
        values
            .into_iter()
            .map(|value| {
                let item: Item<History> = decode_item(value, &context)?;
                Ok(MemberHistory {
                    parliament_member_id: item.value.id,
                    house_memberships: item
                        .value
                        .house_membership_history
                        .into_iter()
                        .map(|period| HouseMembership {
                            house: period.house,
                            start_date: period.start_date.0,
                            end_date: period.end_date.map(|d| d.0),
                        })
                        .collect(),
                })
            })
            .collect()
    }
}

fn failure(message: impl Display) -> ParliamentApiError {
    ParliamentApiError(message.to_string())
}
fn decode<T: DeserializeOwned>(bytes: &[u8], context: &str) -> Result<T, ParliamentApiError> {
    let mut deserializer = serde_json::Deserializer::from_slice(bytes);
    let result = serde_path_to_error::deserialize(&mut deserializer)
        .map_err(|error| failure(format!("{context}: {error}")))?;
    deserializer
        .end()
        .map_err(|error| failure(format!("{context}: {error}")))?;
    Ok(result)
}
fn decode_item<T: DeserializeOwned>(value: Value, context: &str) -> Result<T, ParliamentApiError> {
    let id = value
        .pointer("/value/id")
        .map_or_else(|| "unknown".into(), Value::to_string);
    serde_path_to_error::deserialize(value)
        .map_err(|error| failure(format!("{context}, member {id}: {error}")))
}
fn retry_delay(header: &str) -> Option<Duration> {
    if let Ok(seconds) = header.parse::<f64>() {
        return seconds
            .is_finite()
            .then(|| Duration::from_secs_f64(seconds.clamp(0.0, 30.0)));
    }
    httpdate::parse_http_date(header).ok().map(|date| {
        date.duration_since(SystemTime::now())
            .unwrap_or_default()
            .min(Duration::from_secs(30))
    })
}

#[derive(Deserialize)]
struct Item<T> {
    value: T,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SearchPage {
    items: Vec<Value>,
    total_results: usize,
    skip: usize,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Profile {
    id: i32,
    name_display_as: String,
    latest_party: Option<Party>,
    latest_house_membership: LatestMembership,
}
#[derive(Deserialize)]
struct Party {
    id: Option<i32>,
    name: Option<String>,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct LatestMembership {
    house: i16,
    membership_from: Option<String>,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct History {
    id: i32,
    house_membership_history: Vec<Membership>,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Membership {
    house: i16,
    #[serde(rename = "membershipStartDate")]
    start_date: SourceDate,
    #[serde(rename = "membershipEndDate")]
    end_date: Option<SourceDate>,
}

struct SourceDate(NaiveDate);
impl<'de> Deserialize<'de> for SourceDate {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let value = String::deserialize(deserializer)?;
        let date = NaiveDate::parse_from_str(&value, "%Y-%m-%d")
            .or_else(|_| DateTime::parse_from_rfc3339(&value).map(|d| d.date_naive()))
            .or_else(|_| {
                NaiveDateTime::parse_from_str(&value, "%Y-%m-%dT%H:%M:%S%.f").map(|d| d.date())
            })
            .or_else(|_| {
                NaiveDateTime::parse_from_str(&value, "%Y-%m-%d %H:%M:%S%.f").map(|d| d.date())
            })
            .map_err(serde::de::Error::custom)?;
        Ok(Self(date))
    }
}

