//! PostgreSQL reconciliation of one complete, prevalidated Commons refresh.
use crate::domain::{
    models::member_ingestion::{MemberImport, MemberImportSummary, MemberRecord, MemberRefresh},
    repositories::member_writer::{MemberWriteError, MemberWriter},
};
use anyhow::{Context, ensure};
use chrono::{DateTime, NaiveDate, Utc};
use sqlx::{Connection, PgConnection, Postgres, Row, Transaction, postgres::PgConnectOptions};
use std::{str::FromStr, time::Duration};
use uuid::Uuid;

/// Offline member writer; construction validates configuration without connecting.
#[derive(Clone)]
pub struct MemberDatabase {
    options: PgConnectOptions,
}
impl MemberDatabase {
    /// Store validated connection settings for a later atomic refresh.
    ///
    /// # Errors
    /// Rejects an empty or invalid PostgreSQL connection string.
    pub fn new(connection_string: &str) -> Result<Self, MemberWriteError> {
        if connection_string.trim().is_empty() {
            return Err(MemberWriteError(
                "connection_string must not be empty".into(),
            ));
        }
        let options = PgConnectOptions::from_str(connection_string)
            .map_err(|_| MemberWriteError("invalid PostgreSQL connection string".into()))?
            .application_name("exposed-member-load");
        Ok(Self { options })
    }

    async fn write(&self, refresh: &MemberRefresh) -> anyhow::Result<MemberImportSummary> {
        let mut connection = tokio::time::timeout(
            Duration::from_secs(10),
            PgConnection::connect_with(&self.options),
        )
        .await
        .context("PostgreSQL connection timed out")?
        .context("connect to PostgreSQL")?;
        let mut transaction = connection.begin().await?;
        let term_id = ensure_term(&mut transaction, refresh.term_start).await?;
        let mut summary = MemberImportSummary {
            excluded_candidates: refresh.excluded_candidates,
            ..MemberImportSummary::default()
        };
        for import in &refresh.members {
            let change = write_member(&mut transaction, term_id, import)
                .await
                .with_context(|| format!("member {}", import.member.parliament_member_id))?;
            match change {
                ProfileChange::Inserted => summary.inserted += 1,
                ProfileChange::Updated => summary.updated += 1,
                ProfileChange::Unchanged => summary.unchanged += 1,
            }
            summary.members += 1;
            if import.member.is_current_commons {
                summary.current_commons += 1;
            } else {
                summary.former_commons += 1;
            }
            summary.service_periods += import.periods.len();
        }
        transaction
            .commit()
            .await
            .context("commit member refresh")?;
        Ok(summary)
    }
}
impl MemberWriter for MemberDatabase {
    async fn refresh_members(
        &self,
        refresh: &MemberRefresh,
    ) -> Result<MemberImportSummary, MemberWriteError> {
        self.write(refresh)
            .await
            .map_err(|error| MemberWriteError(format!("{error:#}")))
    }
}

enum ProfileChange {
    Inserted,
    Updated,
    Unchanged,
}

const fn midnight(date: NaiveDate) -> DateTime<Utc> {
    date.and_time(chrono::NaiveTime::MIN).and_utc()
}

async fn ensure_term(
    transaction: &mut Transaction<'_, Postgres>,
    start: NaiveDate,
) -> anyhow::Result<Uuid> {
    let terms: Vec<(Uuid, DateTime<Utc>)> =
        sqlx::query_as("SELECT id, term_start FROM exposed.parliament_terms")
            .fetch_all(&mut **transaction)
            .await?;
    ensure!(
        terms.iter().all(|(_, date)| *date == midnight(start)),
        "database contains another term; this operation refreshes one configured Parliament"
    );
    if let Some((id, _)) = terms.first() {
        return Ok(*id);
    }
    let id = sqlx::query_scalar(
        "INSERT INTO exposed.parliament_terms (id, term_start) VALUES ($1, $2) RETURNING id",
    )
    .bind(Uuid::now_v7())
    .bind(midnight(start))
    .fetch_one(&mut **transaction)
    .await?;
    Ok(id)
}

async fn write_member(
    transaction: &mut Transaction<'_, Postgres>,
    term_id: Uuid,
    import: &MemberImport,
) -> anyhow::Result<ProfileChange> {
    let member = &import.member;
    let previous = sqlx::query("SELECT parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons FROM exposed.members WHERE parliament_member_id = $1")
        .bind(member.parliament_member_id).fetch_optional(&mut **transaction).await?;
    let change = if let Some(row) = previous {
        let stored = MemberRecord {
            parliament_member_id: row.try_get("parliament_member_id")?,
            name: row.try_get("name")?,
            party_id: row.try_get("party_id")?,
            party_name: row.try_get("party_name")?,
            latest_house: row.try_get("latest_house")?,
            latest_membership_from: row.try_get("latest_membership_from")?,
            is_current_commons: row.try_get("is_current_commons")?,
        };
        if stored == *member {
            ProfileChange::Unchanged
        } else {
            ProfileChange::Updated
        }
    } else {
        ProfileChange::Inserted
    };
    let member_id: Uuid = sqlx::query_scalar(
        "INSERT INTO exposed.members (id, parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
         ON CONFLICT (parliament_member_id) DO UPDATE SET name = EXCLUDED.name,
           party_id = EXCLUDED.party_id, party_name = EXCLUDED.party_name,
           latest_house = EXCLUDED.latest_house, latest_membership_from = EXCLUDED.latest_membership_from,
           is_current_commons = EXCLUDED.is_current_commons RETURNING id")
        .bind(Uuid::now_v7()).bind(member.parliament_member_id).bind(&member.name).bind(member.party_id)
        .bind(&member.party_name).bind(member.latest_house).bind(&member.latest_membership_from).bind(member.is_current_commons)
        .fetch_one(&mut **transaction).await?;
    for period in &import.periods {
        sqlx::query(
            "INSERT INTO exposed.member_terms (id, member_id, term_id, house, source_start_date, source_end_date, served_from, served_until)
             VALUES ($1, $2, $3, 1, $4, $5, $6, $5)
             ON CONFLICT (member_id, term_id, house, source_start_date) DO UPDATE SET
                source_end_date = EXCLUDED.source_end_date, served_from = EXCLUDED.served_from, served_until = EXCLUDED.served_until")
            .bind(Uuid::now_v7()).bind(member_id).bind(term_id).bind(midnight(period.source_start_date))
            .bind(period.source_end_date.map(midnight)).bind(midnight(period.served_from)).execute(&mut **transaction).await?;
    }
    let starts: Vec<_> = import
        .periods
        .iter()
        .map(|p| midnight(p.source_start_date))
        .collect();
    sqlx::query("DELETE FROM exposed.member_terms WHERE member_id = $1 AND term_id = $2 AND (house <> 1 OR NOT (source_start_date = ANY($3)))")
        .bind(member_id).bind(term_id).bind(starts).execute(&mut **transaction).await?;
    Ok(change)
}
//! Acquisition and offline loading, with separate infrastructure capabilities.
use crate::domain::{
    models::{
        entity_ingestion::{
            EntityIngestionError, EntityIngestionOutcome, EntityIngestionRequest,
            EntityIngestionTarget, MemberIngestionStage,
        },
        member_ingestion::{
            CaptureContext, CaptureId, MemberCapture, MemberObservations, MemberProfile, invalid,
        },
    },
    repositories::{
        entity_ingestion_pipline::EntityIngestionStorage, member_writer::MemberWriter,
        parliament_api::ParliamentApi,
    },
};
use chrono::{DateTime, NaiveDate, Utc};
use interface::EntitySearchIngestionService;
use std::collections::{BTreeMap, BTreeSet};

/// Public service boundary used by inbound adapters.
pub mod interface;

/// Capture orchestration. It has no database capability.
#[derive(Clone)]
pub struct FetchService<S, P> {
    storage: S,
    source: P,
    started_at: DateTime<Utc>,
    observation_date: NaiveDate,
}
impl<S, P> FetchService<S, P> {
    /// Supply source/storage adapters and one fixed observation context.
    #[must_use]
    pub const fn new(
        storage: S,
        source: P,
        started_at: DateTime<Utc>,
        observation_date: NaiveDate,
    ) -> Self {
        Self {
            storage,
            source,
            started_at,
            observation_date,
        }
    }
}
impl<S: EntityIngestionStorage, P: ParliamentApi> EntitySearchIngestionService
    for FetchService<S, P>
{
    async fn run_ingestion(
        &self,
        req: &EntityIngestionRequest,
    ) -> Result<EntityIngestionOutcome, EntityIngestionError> {
        let capture_id = CaptureId::new();
        let EntityIngestionTarget::Members(MemberIngestionStage::Fetch { term_start }) =
            req.target()
        else {
            return Err(EntityIngestionError::InvalidStage(
                "this service supports member Fetch".into(),
            ));
        };
        if *term_start > self.observation_date {
            return Err(invalid("term start is after observation date"));
        }
        eprintln!("Capture {capture_id}: fetching current Commons observations");
        let current_commons = unique_profiles(self.source.current_commons().await?)?
            .into_keys()
            .collect();
        eprintln!(
            "Capture {capture_id}: fetching historical Commons candidates since {term_start}"
        );
        let profiles = unique_profiles(
            self.source
                .commons_candidates(*term_start, self.observation_date)
                .await?,
        )?;
        let ids: Vec<_> = profiles.keys().copied().collect();
        let mut histories = Vec::new();
        for batch in ids.chunks(100) {
            let returned = self.source.member_histories(batch).await?;
            let returned_ids: BTreeSet<_> =
                returned.iter().map(|h| h.parliament_member_id).collect();
            if returned_ids.len() != returned.len()
                || returned_ids != batch.iter().copied().collect()
            {
                return Err(invalid(format!(
                    "history response must match requested member IDs exactly: {batch:?}; returned {returned_ids:?}"
                )));
            }
            histories.extend(returned);
        }
        histories.sort_by_key(|history| history.parliament_member_id);
        let observations = MemberObservations {
            profiles: profiles.into_values().collect(),
            current_commons,
            histories,
        };
        observations.validate()?;
        let counts = observations.counts();
        let capture = MemberCapture {
            context: CaptureContext {
                capture_id,
                term_start: *term_start,
                observation_date: self.observation_date,
                started_at: self.started_at,
            },
            observations,
        };
        let capture_id = self.storage.write_member_capture(capture).await?;
        Ok(EntityIngestionOutcome::Fetch { capture_id, counts })
    }
}

/// Offline loading. Source access is absent from its contract.
#[derive(Clone)]
pub struct LoadService<S, W> {
    storage: S,
    writer: W,
}
impl<S, W> LoadService<S, W> {
    /// Supply completed-capture storage and an atomic member writer.
    #[must_use]
    pub const fn new(storage: S, writer: W) -> Self {
        Self { storage, writer }
    }
}
impl<S: EntityIngestionStorage, W: MemberWriter> EntitySearchIngestionService
    for LoadService<S, W>
{
    async fn run_ingestion(
        &self,
        req: &EntityIngestionRequest,
    ) -> Result<EntityIngestionOutcome, EntityIngestionError> {
        let EntityIngestionTarget::Members(MemberIngestionStage::Load { capture_id }) =
            req.target()
        else {
            return Err(EntityIngestionError::InvalidStage(
                "this service supports member Load".into(),
            ));
        };
        eprintln!("Capture {capture_id}: validating offline member data");
        let capture = self.storage.read_member_capture(*capture_id).await?;
        let refresh = capture.prepare_refresh()?;
        eprintln!(
            "Capture {capture_id}: loading {} eligible members",
            refresh.members.len()
        );
        let summary = self.writer.refresh_members(&refresh).await?;
        Ok(EntityIngestionOutcome::Load {
            capture_id: *capture_id,
            term_start: capture.context.term_start,
            observation_date: capture.context.observation_date,
            summary,
        })
    }
}

fn unique_profiles(
    profiles: Vec<MemberProfile>,
) -> Result<BTreeMap<i32, MemberProfile>, EntityIngestionError> {
    let mut unique = BTreeMap::new();
    for profile in profiles {
        let id = profile.parliament_member_id;
        if id <= 0 {
            return Err(invalid(format!(
                "member {id}: source identity must be positive"
            )));
        }
        if let Some(previous) = unique.get(&id) {
            if previous != &profile {
                return Err(invalid(format!(
                    "member {id}: conflicting duplicate profile"
                )));
            }
            eprintln!("Member {id}: identical repeated profile collapsed");
        } else {
            unique.insert(id, profile);
        }
    }
    Ok(unique)
}
//! Atomic publication of an already validated member refresh.
use crate::domain::models::member_ingestion::{MemberImportSummary, MemberRefresh};
use thiserror::Error;

/// Database capability used only by Load.
pub trait MemberWriter: Clone + Send + Sync + 'static {
    /// Check the stored Parliament and reconcile all members in one transaction.
    fn refresh_members(
        &self,
        refresh: &MemberRefresh,
    ) -> impl Future<Output = Result<MemberImportSummary, MemberWriteError>> + Send;
}

/// Database failure; no successful summary is returned before commit.
#[derive(Error, Debug)]
#[error("{0}")]
pub struct MemberWriteError(pub String);
//! Source observations needed to reproduce a configured Commons cohort.
use crate::domain::models::member_ingestion::{MemberHistory, MemberProfile};
use chrono::NaiveDate;
use thiserror::Error;

/// Parliament source capability, used only by Fetch.
pub trait ParliamentApi: Clone + Send + Sync + 'static {
    /// Current Commons profiles, retaining repeats for comparison within this stream.
    fn current_commons(
        &self,
    ) -> impl Future<Output = Result<Vec<MemberProfile>, ParliamentApiError>> + Send;
    /// Historical candidates without filtering on their latest House or current status.
