#[error("{0}")]
pub struct ParliamentApiError(pub String);
//! Typed requests and outcomes for independent ingestion operations.

use super::member_ingestion::{CaptureCounts, CaptureId, MemberImportSummary};
use crate::domain::repositories::{
    entity_ingestion_pipline::EntitySearchPipelineError, member_writer::MemberWriteError,
    parliament_api::ParliamentApiError,
};
use chrono::NaiveDate;
use serde::Serialize;
use std::str::FromStr;
use strum::EnumString;
use thiserror::Error;

/// A single explicitly selected ingestion operation.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EntityIngestionRequest {
    target: EntityIngestionTarget,
}

impl EntityIngestionRequest {
    /// Select member acquisition or offline loading.
    #[must_use]
    pub const fn new_members_request(stage: MemberIngestionStage) -> Self {
        Self {
            target: EntityIngestionTarget::Members(stage),
        }
    }
    /// Select an existing declaration stage (implementation is deferred).
    ///
    /// # Errors
    /// Returns an error for an unknown stage name.
    pub fn new_declaration_request(stage: &str) -> Result<Self, EntityIngestionError> {
        let stage = DeclarationIngestionStage::from_str(stage)
            .map_err(|_| EntityIngestionError::InvalidStage(stage.to_string()))?;
        Ok(Self {
            target: EntityIngestionTarget::Declaration(stage),
        })
    }
    /// Operation selected by this request.
    #[must_use]
    pub const fn target(&self) -> &EntityIngestionTarget {
        &self.target
    }
}

/// Ingestion targets.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum EntityIngestionTarget {
    /// Member capture or database publication.
    Members(MemberIngestionStage),
    /// Declaration stages remain deferred.
    Declaration(DeclarationIngestionStage),
}

/// Independent member operations with distinct inputs.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MemberIngestionStage {
    /// Acquire source data for the configured Parliament.
    Fetch {
        /// Beginning of the Parliament cohort.
        term_start: NaiveDate,
    },
    /// Apply a completed capture entirely offline from Parliament.
    Load {
        /// Explicit `UUIDv7` of the saved input.
        capture_id: CaptureId,
    },
}

/// From what stage to run the declaration pipeline.
#[derive(Clone, Debug, PartialEq, Eq, EnumString)]
#[allow(missing_docs)]
#[strum(ascii_case_insensitive)]
pub enum DeclarationIngestionStage {
    Import,
    Clean,
    Resolve,
}

/// Success is returned only after finalization or transaction commit.
#[derive(Clone, Debug, Serialize)]
#[serde(tag = "operation", rename_all = "snake_case")]
pub enum EntityIngestionOutcome {
    /// Completed immutable source capture.
    Fetch {
        /// Completed capture identity.
        capture_id: CaptureId,
        /// Raw dataset row counts.
        counts: CaptureCounts,
    },
    /// Committed database refresh.
    Load {
        /// Explicit capture used for the refresh.
        capture_id: CaptureId,
        /// Captured term start.
        term_start: NaiveDate,
        /// Captured observation date.
        observation_date: NaiveDate,
        /// Committed member outcomes.
        summary: MemberImportSummary,
    },
}

/// Failures while acquiring, validating or publishing ingestion data.
#[derive(Error, Debug)]
pub enum EntityIngestionError {
    /// Source request or decoding failure.
    #[error("Parliament source: {0}")]
    ApiError(#[from] ParliamentApiError),
    /// Invalid source observations or service rules.
    #[error("invalid member data: {0}")]
    DataError(String),
    /// Capture storage failure.
    #[error("capture storage: {0}")]
    IoError(#[from] EntitySearchPipelineError),
    /// Atomic database refresh failed.
    #[error("member load: {0}")]
    DatabaseError(#[from] MemberWriteError),
    /// Invalid or unavailable stage.
    #[error("unsupported ingestion stage: {0}")]
    InvalidStage(String),
}
//! Command-line inbound adapter, including configuration and service construction.

use crate::{
    config::{Config, MemberFetchConfig, MemberLoadConfig, read_data_config},
    domain::{
        models::{
            entity_ingestion::{
                EntityIngestionOutcome, EntityIngestionRequest, MemberIngestionStage,
            },
            member_ingestion::CaptureId,
        },
        services::entity_ingestion::{
            FetchService, LoadService, interface::EntitySearchIngestionService,
        },
    },
    inbound::http::server::serve_exposed,
    outbound::{ExposedDataPipeline, MemberDatabase, MembersApi},
};
use anyhow::{Context, ensure};
use chrono::Utc;
use clap::{Args, Parser, Subcommand};
use std::{path::PathBuf, process::ExitCode};

#[derive(Parser)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}
#[derive(Subcommand)]
enum Commands {
    Server { config: PathBuf },
    Data(DataArgs),
}
#[derive(Args)]
struct DataArgs {
    #[command(subcommand)]
    command: DataCommands,
}
#[derive(Subcommand)]
enum DataCommands {
    Fetch {
        #[command(subcommand)]
        target: FetchTarget,
    },
    Load {
        #[command(subcommand)]
        target: LoadTarget,
    },
    Clean {
        config: PathBuf,
    },
    Resolve {
        config: PathBuf,
    },
}
#[derive(Subcommand)]
enum FetchTarget {
    Members { config: PathBuf },
}
#[derive(Subcommand)]
enum LoadTarget {
    Members {
        config: PathBuf,
        capture_id: CaptureId,
    },
}

/// Run the CLI using process arguments and return its exit status.
///
/// Owns command dispatch, service construction, output and interruption handling.
pub async fn run() -> ExitCode {
    let args = Cli::parse();
    // Dropping the operation on Ctrl-C drops an in-flight transaction. Capture
    // publication is synchronous once source acquisition has finished.
    tokio::select! {
        result = dispatch(args) => match result {
            Ok(()) => ExitCode::SUCCESS,
            Err(error) => {
                let code = if error.is::<InvalidConfiguration>() { 2 } else { 1 };
                eprintln!("{error:#}");
                ExitCode::from(code)
            }
        },
        _ = tokio::signal::ctrl_c() => { eprintln!("Interrupted"); ExitCode::from(130) }
    }
}
async fn dispatch(args: Cli) -> anyhow::Result<()> {
    let outcome: EntityIngestionOutcome = match args.command {
        Commands::Server { config } => {
            return serve_exposed(&Config::try_from(&config)?).await;
        }
        Commands::Data(DataArgs {
            command:
                DataCommands::Fetch {
                    target: FetchTarget::Members { config },
                },
        }) => {
            let started_at = Utc::now();
            let observation_date = started_at
                .with_timezone(&chrono_tz::Europe::London)
                .date_naive();
            let config: MemberFetchConfig = read_data_config(&config)
                .context(InvalidConfiguration("invalid member Fetch configuration"))?;
            ensure!(
                !config.data_root.as_os_str().is_empty(),
                InvalidConfiguration("data_root must not be empty")
            );
            let source = MembersApi::new(&config.members_api_url)
                .context(InvalidConfiguration("invalid Members API configuration"))?;
            let storage = ExposedDataPipeline::new(config.data_root);
            FetchService::new(storage, source, started_at, observation_date)
                .run_ingestion(&EntityIngestionRequest::new_members_request(
                    MemberIngestionStage::Fetch {
                        term_start: config.term_start,
                    },
                ))
                .await?
        }
        Commands::Data(DataArgs {
            command:
                DataCommands::Load {
                    target: LoadTarget::Members { config, capture_id },
                },
        }) => {
            let config: MemberLoadConfig = read_data_config(&config)
                .context(InvalidConfiguration("invalid member Load configuration"))?;
            ensure!(
                !config.data_root.as_os_str().is_empty(),
                InvalidConfiguration("data_root must not be empty")
            );
            let storage = ExposedDataPipeline::new(config.data_root);
            let database = MemberDatabase::new(&config.connection_string).context(
                InvalidConfiguration("invalid member database configuration"),
            )?;
            LoadService::new(storage, database)
                .run_ingestion(&EntityIngestionRequest::new_members_request(
                    MemberIngestionStage::Load { capture_id },
                ))
                .await?
        }
        Commands::Data(_) => {
            anyhow::bail!("declaration cleaning and resolution are not implemented")
        }
    };
    let mut summary = serde_json::to_value(outcome)?;
    summary["status"] = "succeeded".into();
    println!("{}", serde_json::to_string(&summary)?);
    Ok(())
}

#[derive(Debug, thiserror::Error)]
#[error("{0}")]
struct InvalidConfiguration(&'static str);

