                    parliament_member_id: item.value.id,
                    house_memberships: item
                        .value
                        .house_membership_history
                        .into_iter()
                        .map(|period| HouseMembership {
                            house: period.house,
                            start_date: period.start_date.0,
                            end_date: period.end_date.map(|d| d.0),
                        })
