        assert_eq!(results.len(), 1);
        assert_eq!(results.first().unwrap().0.name(), "John McDonnell");

        Ok(())
    }

    #[sqlx::test(
        migrations = "../db/migrations",
        fixtures(
            "../../../../db/fixtures/add_members.sql",
            "../../../../db/fixtures/add_declarations_and_funding_entries.sql"
        )
    )]
    async fn filters_similarity(pool: PgPool) -> sqlx::Result<()> {
        let db = ExposedDatabase::from(pool);

        let term = EntitySearchRequest::new_strict("John McDonnell".into(), 5).unwrap();
        let results = db.get_members_by_text_search_score(&term).await.unwrap();

        assert_eq!(results.len(), 1);
        assert_eq!(results.first().unwrap().0.name(), "John McDonnell");

        Ok(())
    }
}
//! Source observations needed to reproduce a configured Commons cohort.
use chrono::NaiveDate;
use thiserror::Error;

/// Parliament source capability, used only by Fetch.
pub trait ParliamentApi: Clone + Send + Sync + 'static {
    /// Current Commons observations, retaining repeats for comparison within this stream.
    fn current_commons(
        &self,
    ) -> impl Future<Output = Result<Vec<MemberObservation>, ParliamentApiError>> + Send;
    /// Historical candidates without filtering on their latest House or current status.
    fn commons_candidates(
        &self,
        term_start: NaiveDate,
        observation_date: NaiveDate,
    ) -> impl Future<Output = Result<Vec<MemberObservation>, ParliamentApiError>> + Send;
    /// Histories for the requested IDs, retaining returned identities and duplicates.
    fn member_histories(
        &self,
        member_ids: &[i32],
    ) -> impl Future<Output = Result<Vec<MemberHistory>, ParliamentApiError>> + Send;
}

/// Source failure with request and field context.
#[derive(Error, Debug)]
#[error("{0}")]
pub struct ParliamentApiError(pub String);

/// A source profile as observed, before acceptance as a domain member.
/// Nullable fields reflect omissions in the source and remain nullable in raw storage.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MemberObservation {
    parliament_member_id: i32,
    name: String,
    party_id: Option<i32>,
    party_name: Option<String>,
    latest_house: i16,
    latest_membership_from: Option<String>,
}

impl MemberObservation {
    /// Accept the fields captured from one source profile.
    ///
    /// # Errors
    /// Rejects invalid source identities, names, parties and Houses.
    pub fn new(
        parliament_member_id: i32,
        name: String,
        party_id: Option<i32>,
        party_name: Option<String>,
        latest_house: i16,
        latest_membership_from: Option<String>,
    ) -> Result<Self, ParliamentApiError> {
        if parliament_member_id <= 0
            || name.trim().is_empty()
            || party_id.is_some_and(|id| id <= 0)
            || !matches!(latest_house, 1 | 2)
        {
            return Err(ParliamentApiError(format!(
                "member {parliament_member_id}: invalid source identity, name, party_id or latest_house"
            )));
        }
        Ok(Self {
            parliament_member_id,
            name,
            party_id,
            party_name,
            latest_house,
            latest_membership_from,
        })
    }
    /// Parliament's numeric identity.
    #[must_use]
    pub const fn parliament_member_id(&self) -> i32 {
        self.parliament_member_id
    }
    /// Source display name, without normalization.
    #[must_use]
    pub fn name(&self) -> &str {
        &self.name
    }
    /// Latest party identity when supplied.
    #[must_use]
    pub const fn party_id(&self) -> Option<i32> {
        self.party_id
    }
    /// Latest party name when supplied.
    #[must_use]
    pub fn party_name(&self) -> Option<&str> {
        self.party_name.as_deref()
    }
    /// Latest House observed in this profile.
    #[must_use]
    pub const fn latest_house(&self) -> i16 {
        self.latest_house
    }
    /// Latest membership location when supplied.
    #[must_use]
    pub fn latest_membership_from(&self) -> Option<&str> {
        self.latest_membership_from.as_deref()
    }
}

/// One source House membership, before term clipping or deduplication.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct HouseMembership {
    house: i16,
    start_date: NaiveDate,
    end_date: Option<NaiveDate>,
}
impl HouseMembership {
    /// Accept a source period without deriving Commons service from it.
    ///
    /// # Errors
    /// Rejects an unknown House or an end date before the start.
    pub fn new(
        house: i16,
        start_date: NaiveDate,
        end_date: Option<NaiveDate>,
    ) -> Result<Self, ParliamentApiError> {
        if !matches!(house, 1 | 2) || end_date.is_some_and(|end| end < start_date) {
            return Err(ParliamentApiError(
                "invalid House or membership date ordering".into(),
            ));
        }
        Ok(Self {
            house,
            start_date,
            end_date,
        })
    }
    /// Commons (1) or Lords (2).
    #[must_use]
    pub const fn house(&self) -> i16 {
        self.house
    }
    /// Source calendar start date.
    #[must_use]
    pub const fn start_date(&self) -> NaiveDate {
        self.start_date
    }
    /// Date service ceased, if supplied.
    #[must_use]
    pub const fn end_date(&self) -> Option<NaiveDate> {
        self.end_date
    }
}

/// A returned history, retaining its source identity and every period.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MemberHistory {
    parliament_member_id: i32,
    house_memberships: Vec<HouseMembership>,
}
impl MemberHistory {
    /// Accept one identified, nonempty source history.
    ///
    /// # Errors
    /// Rejects an invalid member identity or an empty history.
    pub fn new(
        parliament_member_id: i32,
        house_memberships: Vec<HouseMembership>,
    ) -> Result<Self, ParliamentApiError> {
        if parliament_member_id <= 0 || house_memberships.is_empty() {
            return Err(ParliamentApiError(format!(
                "member {parliament_member_id}: invalid identity or empty history"
            )));
        }
        Ok(Self {
            parliament_member_id,
            house_memberships,
        })
    }
    /// Parliament's numeric identity.
    #[must_use]
    pub const fn parliament_member_id(&self) -> i32 {
        self.parliament_member_id
    }
    /// All source periods, including identical repeats.
    #[must_use]
    pub fn house_memberships(&self) -> &[HouseMembership] {
        &self.house_memberships
    }
}
//! Acquisition and offline loading, with separate infrastructure capabilities.
use crate::domain::{
    models::{
        entity_ingestion::{
            EntityIngestionError, EntityIngestionOutcome, EntityIngestionRequest,
            EntityIngestionTarget, MemberIngestionStage,
        },
        member_ingestion::{
            CaptureContext, CaptureId, MemberCapture, MemberObservations, MemberRefresh, invalid,
        },
    },
    repositories::{
        entity_ingestion_pipline::EntityIngestionStorage,
        parliament_api::{MemberHistory, MemberObservation, ParliamentApi},
        parliament_member_repository::ParliamentMemberRepo,
    },
};
use chrono::{DateTime, NaiveDate, Utc};
use interface::EntitySearchIngestionService;
use std::collections::{BTreeMap, BTreeSet};

/// Public service boundary used by inbound adapters.
pub mod interface;

/// Capture orchestration. It has no database capability.
#[derive(Clone)]
pub struct FetchService<S, P> {
    storage: S,
    source: P,
    started_at: DateTime<Utc>,
    observation_date: NaiveDate,
}
impl<S, P> FetchService<S, P> {
    /// Supply source/storage adapters and one fixed observation context.
    #[must_use]
    pub const fn new(
        storage: S,
        source: P,
        started_at: DateTime<Utc>,
        observation_date: NaiveDate,
    ) -> Self {
        Self {
            storage,
            source,
            started_at,
            observation_date,
        }
    }
}
impl<S: EntityIngestionStorage, P: ParliamentApi> EntitySearchIngestionService
    for FetchService<S, P>
{
    async fn run_ingestion(
        &self,
        req: &EntityIngestionRequest,
    ) -> Result<EntityIngestionOutcome, EntityIngestionError> {
        let capture_id = CaptureId::new();
        let EntityIngestionTarget::Members(MemberIngestionStage::Fetch { term_start }) =
            req.target()
        else {
            return Err(EntityIngestionError::InvalidStage(
                "this service supports member Fetch".into(),
            ));
        };
        let context = CaptureContext::new(
            capture_id,
            *term_start,
            self.observation_date,
            self.started_at,
        )?;
        eprintln!("Capture {capture_id}: fetching current Commons observations");
        let current_commons = unique_profiles(self.source.current_commons().await?)?
            .into_keys()
            .collect();
        eprintln!(
            "Capture {capture_id}: fetching historical Commons candidates since {term_start}"
        );
        let profiles = unique_profiles(
            self.source
                .commons_candidates(*term_start, self.observation_date)
                .await?,
        )?;
        let ids: Vec<_> = profiles.keys().copied().collect();
        let mut histories = Vec::new();
        for batch in ids.chunks(100) {
            let returned = self.source.member_histories(batch).await?;
            let returned_ids: BTreeSet<_> = returned
                .iter()
                .map(MemberHistory::parliament_member_id)
                .collect();
            if returned_ids.len() != returned.len()
                || returned_ids != batch.iter().copied().collect()
            {
                return Err(invalid(format!(
                    "history response must match requested member IDs exactly: {batch:?}; returned {returned_ids:?}"
                )));
            }
            histories.extend(returned);
        }
        let observations =
            MemberObservations::new(profiles.into_values().collect(), current_commons, histories)?;
        let capture = MemberCapture::new(context, observations);
        let capture_id = self.storage.write_member_capture(capture).await?;
        Ok(EntityIngestionOutcome::Fetch { capture_id })
    }
}

/// Offline loading. Source access is absent from its contract.
#[derive(Clone)]
pub struct LoadService<S, W> {
    storage: S,
    writer: W,
}
impl<S, W> LoadService<S, W> {
    /// Supply completed-capture storage and an atomic member writer.
    #[must_use]
    pub const fn new(storage: S, writer: W) -> Self {
        Self { storage, writer }
    }
}
impl<S: EntityIngestionStorage, W: ParliamentMemberRepo> EntitySearchIngestionService
    for LoadService<S, W>
{
    async fn run_ingestion(
        &self,
        req: &EntityIngestionRequest,
    ) -> Result<EntityIngestionOutcome, EntityIngestionError> {
        let EntityIngestionTarget::Members(MemberIngestionStage::Load { capture_id }) =
            req.target()
        else {
            return Err(EntityIngestionError::InvalidStage(
                "this service supports member Load".into(),
            ));
        };
        eprintln!("Capture {capture_id}: validating offline member data");
        let capture = self.storage.read_member_capture(*capture_id).await?;
        let refresh = MemberRefresh::from_capture(&capture)?;
        eprintln!(
            "Capture {capture_id}: loading {} eligible members",
            refresh.members().len()
        );
        self.writer.refresh_members(&refresh).await?;
        Ok(EntityIngestionOutcome::Load {
            capture_id: *capture_id,
            term_start: capture.context().term_start(),
            observation_date: capture.context().observation_date(),
        })
    }
}

fn unique_profiles(
    profiles: Vec<MemberObservation>,
) -> Result<BTreeMap<i32, MemberObservation>, EntityIngestionError> {
    let mut unique = BTreeMap::new();
    for profile in profiles {
        let id = profile.parliament_member_id();
        if let Some(previous) = unique.get(&id) {
            if previous != &profile {
                return Err(invalid(format!(
                    "member {id}: conflicting duplicate profile"
                )));
            }
            eprintln!("Member {id}: identical repeated profile collapsed");
        } else {
            unique.insert(id, profile);
        }
    }
    Ok(unique)
}
"}

