//! Validated members used by both search and member ingestion.
use thiserror::Error;

/// Member of Parliament with the required profile and current Commons status.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ParliamentMember {
    name: String,
    member_id: i32,
    party_id: i32,
    party_name: String,
    latest_house: i16,
    latest_membership_from: String,
    is_current_commons: bool,
}

impl ParliamentMember {
    /// Create a member whose profile and current status are consistent.
    ///
    /// # Errors
    /// Rejects invalid identities, a blank name, an unknown House, or current
    /// Commons status with a latest Lords profile.
    pub fn new(
        name: String,
        parliament_member_id: i32,
        party_id: i32,
        party_name: String,
        latest_house: i16,
        latest_membership_from: String,
        is_current_commons: bool,
    ) -> Result<Self, ParliamentMemberError> {
        if parliament_member_id <= 0 {
            return Err(ParliamentMemberError::InvalidField {
                member_id: parliament_member_id,
                field: "parliament_member_id",
            });
        }
        if name.trim().is_empty() {
            return Err(ParliamentMemberError::InvalidField {
                member_id: parliament_member_id,
                field: "name",
            });
        }
        if party_id <= 0 {
            return Err(ParliamentMemberError::InvalidField {
                member_id: parliament_member_id,
                field: "party_id",
            });
        }
        if !matches!(latest_house, 1 | 2) || (is_current_commons && latest_house != 1) {
            return Err(ParliamentMemberError::InvalidField {
                member_id: parliament_member_id,
                field: "latest_house",
            });
        }
        Ok(Self {
            name,
            member_id: parliament_member_id,
            party_id,
            party_name,
            latest_house,
            latest_membership_from,
            is_current_commons,
        })
    }
    /// Member's source display name.
    #[must_use]
    pub fn name(&self) -> &str {
        &self.name
    }
    /// Parliament's numeric member identity.
    #[must_use]
    pub const fn parliament_member_id(&self) -> i32 {
        self.member_id
    }
    /// Required latest party identity.
    #[must_use]
    pub const fn party_id(&self) -> i32 {
        self.party_id
    }
    /// Required latest party name.
    #[must_use]
    pub fn party_name(&self) -> &str {
        &self.party_name
    }
    /// Latest House from the member profile.
    #[must_use]
    pub const fn latest_house(&self) -> i16 {
        self.latest_house
    }
    /// Required latest membership location.
    #[must_use]
    pub fn latest_membership_from(&self) -> &str {
        &self.latest_membership_from
    }
    /// Status observed in the current Commons search.
    #[must_use]
    pub const fn is_current_commons(&self) -> bool {
        self.is_current_commons
    }
}

/// A member profile cannot be represented by a valid domain member.
#[derive(Error, Debug)]
pub enum ParliamentMemberError {
    /// A required value is invalid or inconsistent with current membership.
    #[error("member {member_id}: invalid {field}")]
    InvalidField {
        /// Parliament's numeric member identity.
        member_id: i32,
        /// Invalid source field.
        field: &'static str,
    },
}
//! Valid capture identities, complete observations and accepted Commons service.
use super::{entity_ingestion::EntityIngestionError, parliament_member::ParliamentMember};
use crate::domain::repositories::parliament_api::{MemberHistory, MemberObservation};
use chrono::{DateTime, NaiveDate, Utc};
use serde::{Deserialize, Serialize};
use std::{
    collections::{BTreeMap, BTreeSet},
    fmt,
    str::FromStr,
};
use uuid::Uuid;

/// Identity of an immutable capture, ordered by `UUIDv7` creation time.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(try_from = "Uuid", into = "Uuid")]
pub struct CaptureId(Uuid);
impl CaptureId {
    /// Allocate an identity at the beginning of a fetch attempt.
    #[must_use]
    pub fn new() -> Self {
        Self(Uuid::now_v7())
    }
}
impl Default for CaptureId {
    fn default() -> Self {
        Self::new()
    }
}
impl From<CaptureId> for Uuid {
    fn from(id: CaptureId) -> Self {
        id.0
    }
}
impl TryFrom<Uuid> for CaptureId {
    type Error = EntityIngestionError;
    fn try_from(id: Uuid) -> Result<Self, Self::Error> {
        if id.get_version_num() != 7 || id.get_variant() != uuid::Variant::RFC4122 {
            return Err(invalid("capture ID must be a UUIDv7"));
        }
        Ok(Self(id))
    }
}
impl FromStr for CaptureId {
    type Err = EntityIngestionError;
    fn from_str(value: &str) -> Result<Self, Self::Err> {
        Uuid::parse_str(value)
            .map_err(|_| invalid("capture ID must be a UUIDv7"))?
            .try_into()
    }
}
impl fmt::Display for CaptureId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

/// Valid observation context fixed when acquisition begins.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CaptureContext {
    capture_id: CaptureId,
    term_start: NaiveDate,
    observation_date: NaiveDate,
    started_at: DateTime<Utc>,
}
impl CaptureContext {
    /// Create the context used for both acquisition and offline interpretation.
    ///
    /// # Errors
    /// Rejects a term starting after the observation date.
    pub fn new(
        capture_id: CaptureId,
        term_start: NaiveDate,
        observation_date: NaiveDate,
        started_at: DateTime<Utc>,
    ) -> Result<Self, EntityIngestionError> {
        if term_start > observation_date {
            return Err(invalid("term start is after observation date"));
        }
        Ok(Self {
            capture_id,
            term_start,
            observation_date,
            started_at,
        })
    }
    /// Identity allocated for this capture.
    #[must_use]
    pub const fn capture_id(&self) -> CaptureId {
        self.capture_id
    }
    /// Beginning of the Parliament cohort.
    #[must_use]
    pub const fn term_start(&self) -> NaiveDate {
        self.term_start
    }
    /// Fixed calendar date in Europe/London.
    #[must_use]
    pub const fn observation_date(&self) -> NaiveDate {
        self.observation_date
    }
    /// UTC instant at the start of acquisition.
    #[must_use]
    pub const fn started_at(&self) -> DateTime<Utc> {
        self.started_at
    }
}

/// Complete source observations, checked together at construction.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MemberObservations {
    profiles: Vec<MemberObservation>,
    current_commons: BTreeSet<i32>,
    histories: BTreeMap<i32, MemberHistory>,
}
impl MemberObservations {
    /// Accept complete candidate, current and history observations.
    ///
    /// # Errors
    /// Rejects duplicate, missing or unexpected identities in any dataset.
    pub fn new(
        profiles: Vec<MemberObservation>,
        current_commons: Vec<i32>,
        histories: Vec<MemberHistory>,
    ) -> Result<Self, EntityIngestionError> {
        let candidates: BTreeSet<_> = profiles
            .iter()
            .map(MemberObservation::parliament_member_id)
            .collect();
        if candidates.len() != profiles.len() {
            return Err(invalid("duplicate historical candidate identity"));
        }
        let current_count = current_commons.len();
        let current_ids: BTreeSet<_> = current_commons.into_iter().collect();
        if current_ids.len() != current_count || !current_ids.is_subset(&candidates) {
