impl MemberCapture {
    /// Interpret all observations before making any database writes.
    ///
    /// # Errors
    /// Rejects incomplete captures, invalid fields and inconsistent Commons service.
    pub fn prepare_refresh(&self) -> Result<MemberRefresh, EntityIngestionError> {
        self.observations.validate()?;
        let term_start = self.context.term_start;
        let as_of = self.context.observation_date;
        if term_start > as_of {
            return Err(invalid("term start is after observation date"));
        }
        let current: BTreeSet<_> = self.observations.current_commons.iter().copied().collect();
        let histories: BTreeMap<_, _> = self
            .observations
            .histories
            .iter()
            .map(|h| (h.parliament_member_id, h))
            .collect();
        let mut refresh = MemberRefresh {
            term_start,
            members: Vec::new(),
    ) -> Result<Vec<MemberObservation>, ParliamentApiError> {
        self.search(vec![
            (
                "MembershipInDateRange.WasMemberOnOrAfter",
                term_start.to_string(),
            ),
            (
                "MembershipInDateRange.WasMemberOnOrBefore",
                observation_date.to_string(),
            ),
            ("MembershipInDateRange.WasMemberOfHouse", "1".into()),
        ])
        .await
    }
    async fn member_histories(
        &self,
        member_ids: &[i32],
    ) -> Result<Vec<MemberHistory>, ParliamentApiError> {
        if member_ids.is_empty() || member_ids.len() > 100 {
            return Err(failure("history requests require 1–100 member IDs"));
        }
        let params: Vec<_> = member_ids
            .iter()
            .map(|id| ("ids", id.to_string()))
            .collect();
        let items: Vec<Item<History>> = self.get("/api/Members/History", &params).await?;
        items
            .into_iter()
            .map(|item| {
                let id = item.value.id;
                let periods = item
                    .value
                    .house_membership_history
                    .into_iter()
                    .map(|period| {
                        HouseMembership::new(
                            period.house,
                            period.start_date.0,
                            period.end_date.map(|date| date.0),
                        )
                        .map_err(|error| {
                            failure(format!("/api/Members/History, member {id}: {error}"))
                        })
                    })
                    .collect::<Result<Vec<_>, _>>()?;
                MemberHistory::new(id, periods)
                    .map_err(|error| failure(format!("/api/Members/History: {error}")))
            })
            .collect()
    }
}

