                ))
                .await?
        }
        Commands::Data(_) => {
            anyhow::bail!("declaration cleaning and resolution are not implemented")
        }
    };
    let mut outcome = serde_json::to_value(outcome)?;
    outcome["status"] = "succeeded".into();
    println!("{}", serde_json::to_string(&outcome)?);
    Ok(())
}

